import React from "react";

const Sidebar = () => {
    return (
        <div className="sidebar">
            <h2>Sidebar</h2>
            <ul>
                <li><a href="/home">Home</a></li>
                <li><a href="/">Products</a></li>
                <li><a href="/Categories">Categories</a></li>
                <li><a href="/Brand">Brand</a></li>
            </ul>
        </div>
    );};
    export default Sidebar;
